SELECT id, storage_platform, upload_mode, original_name, content_type, size, is_private, biz_type, biz_id, create_time, update_time, create_user, update_user FROM file_record
is_deleted = #{isDeleted}
AND is_private = #{query.isPrivate}
AND delete_source = #{query.deleteSource}
AND create_user = #{query.ownerUserId}
AND biz_type = #{query.bizType}
AND biz_id = #{query.bizId}
AND content_type LIKE CONCAT(#{query.contentType}, '%')
AND original_name LIKE CONCAT('%', #{query.originalName}, '%')
AND create_time >= #{query.startTime} AND create_time <= #{query.endTime}
ORDER BY create_time DESC

